function restoreEndingCopy(){const title=$('finish').querySelector('h1');if(title)title.innerHTML='Chúc mừng sinh nhật,<br><em>Thanh Vy.</em>';const lead=$('finish').querySelector('.lead');if(lead)lead.innerHTML='Kế hoạch tối nay đã được duyệt.<br>Không yêu cầu slide đính kèm.';const over=$('finish').querySelector('.eyebrow');if(over)over.textContent='SURVIVAL COMPLETE / 1.710 M'}
function enterLateEnding(){if(lateEnding>=0)return;endingKind='late';lateEnding=0;objects=[];stopClip();if(noiseGain)noiseGain.gain.value=0;$('controls').hidden=true;$('chapter').textContent='ALTERNATE ENDING / MỘT BUỔI TỐI KHÁC';$('chapterTitle').textContent='Lỡ hẹn với đường đua…';$('bubble').hidden=true;beep(180,.3)}
