const proceduralRoadObstacle=drawRoadObstacle,proceduralScooter=drawScooter;
function trafficSprite(cell,height){const cw=trafficSheet.width/4,ch=trafficSheet.height,width=height*cw/ch;ctx.drawImage(trafficSheet,cell*cw,0,cw,ch,-width/2,-height,width,height)}
drawRoadObstacle=function(type){if(!trafficReady||type===3){proceduralRoadObstacle(type);return}trafficSprite(type===1?0:type===2?1:2,type===1?125:type===2?105:75)};
drawScooter=function(color,rider){if(trafficReady&&rider){trafficSprite(3,95);return}proceduralScooter(color,rider)};
